139	func assertAuthIDsSorted(t *testing.T, auths []Authorization) {
140		t.Helper()
141		for i := 1; i < len(auths); i++ {
142			if auths[i-1].ID >= auths[i].ID {
143				t.Fatalf("authorizations not sorted ascending by id: %q before %q",
144					auths[i-1].ID, auths[i].ID)
145			}
146		}
147	}
148	
149	func assertAuthIDSet(t *testing.T, got []Authorization, want ...ID) {
150		t.Helper()
151		wantSet := map[ID]bool{}
152		for _, id := range want {
153			wantSet[id] = true
154		}
155		gotSet := map[ID]bool{}
156		for _, a := range got {
157			if gotSet[a.ID] {
158				t.Fatalf("authorization %q listed more than once", a.ID)
159			}
160			gotSet[a.ID] = true
161		}
162		if !reflect.DeepEqual(gotSet, wantSet) {
163			t.Fatalf("authorization id set = %v, want %v", gotSet, wantSet)
164		}
165	}
166	
167	func findListedAuth(t *testing.T, auths []Authorization, id ID) Authorization {
168		t.Helper()
169		for _, a := range auths {
170			if a.ID == id {
171				return a
172			}
173		}
174		t.Fatalf("authorization %q missing from list", id)
175		return Authorization{}
176	}
177	
178	func listedAuthByID(auths []Authorization, id ID) (Authorization, bool) {
179		for _, a := range auths {
180			if a.ID == id {
181				return a, true
182			}
183		}
184		return Authorization{}, false
185	}
