193	// ---- 患者与接收方两个条件必须同时成立；按授权标识升序 ----
194	
195	func TestListAuthorizationsFiltersByPatientAndReceiver(t *testing.T) {
196		f := setupListAuthFixture(t)
197	
198		// 不指定接收方：所选患者的全部授权（两名接收方各自的授权都在）。
199		allA, err := f.s.ListAuthorizations(doc, f.pidA, "")
200		if err != nil {
201			t.Fatalf("list patient A: %v", err)
202		}
203		assertAuthIDSet(t, allA, f.active.ID, f.future.ID, f.expired.ID, f.revoked.ID, f.otherRcv.ID)
204		assertAuthIDsSorted(t, allA)
205	
206		// 指定接收方 rcv：患者甲授予 rcv 的四条，按标识升序。
207		aRcv, err := f.s.ListAuthorizations(doc, f.pidA, rcv.ID)
208		if err != nil {
209			t.Fatalf("list A/rcv: %v", err)
210		}
211		assertAuthIDSet(t, aRcv, f.active.ID, f.future.ID, f.expired.ID, f.revoked.ID)
212		assertAuthIDsSorted(t, aRcv)
213		for _, a := range aRcv {
214			if a.PatientID != f.pidA || a.ReceiverID != rcv.ID {
215				t.Fatalf("filter leaked row %+v", a)
216			}
217		}
218	
219		// 不能因为接收方相同而带出患者乙授予 rcv 的授权。
220		if leaked, ok := listedAuthByID(aRcv, f.grantB.ID); ok {
221			t.Fatalf("patient B grant leaked into patient A list via shared receiver: %+v", leaked)
222		}
223	
224		// 指定接收方 rcvB：只留下患者甲授予 rcvB 的一条，
225		// 不能因为患者相同而混入授予 rcv 的授权。
226		aRcvB, err := f.s.ListAuthorizations(doc, f.pidA, rcvB.ID)
227		if err != nil {
228			t.Fatalf("list A/rcvB: %v", err)
229		}
230		assertAuthIDSet(t, aRcvB, f.otherRcv.ID)
231	
232		// 反向核对：查患者乙 + rcv，只能看到乙自己的授权，甲的四条不在其中。
233		bRcv, err := f.s.ListAuthorizations(doc, f.pidB, rcv.ID)
234		if err != nil {
235			t.Fatalf("list B/rcv: %v", err)
236		}
237		assertAuthIDSet(t, bRcv, f.grantB.ID)
238		bAll, err := f.s.ListAuthorizations(doc, f.pidB, "")
239		if err != nil {
240			t.Fatalf("list patient B: %v", err)
241		}
242		assertAuthIDSet(t, bAll, f.grantB.ID)
243	
244		// 存在但没有授权的患者、已有患者搭配从未获其授权的接收方：成功空列表。
245		for _, tc := range []struct{ name, pid, receiver string }{
246			{"patient without authorizations", f.pidC, ""},
247			{"patient C filtered by receiver", f.pidC, rcv.ID},
248			{"patient A filtered by stranger receiver", f.pidA, "rcv-c"},
249			{"patient B filtered by receiver it never granted", f.pidB, rcvB.ID},
250		} {
251			got, err := f.s.ListAuthorizations(doc, tc.pid, tc.receiver)
252			if err != nil {
253				t.Fatalf("%s: %v", tc.name, err)
254			}
255			if len(got) != 0 {
256				t.Fatalf("%s: got %d rows, want empty", tc.name, len(got))
257			}
258		}
259	
260		// 患者不存在：无论是否指定接收方都返回 ErrNotFound。
261		if _, err := f.s.ListAuthorizations(doc, "pat_missing", ""); !errors.Is(err, ErrNotFound) {
262			t.Fatalf("missing patient err = %v, want ErrNotFound", err)
263		}
264		if _, err := f.s.ListAuthorizations(doc, "pat_missing", rcv.ID); !errors.Is(err, ErrNotFound) {
265			t.Fatalf("missing patient with receiver err = %v, want ErrNotFound", err)
266		}
267	}
